                &metrics::BEACON_PROCESSOR_GOSSIP_DATA_COLUMN_SIDECAR_VERIFIED_TOTAL,
            );

            debug!(
                %slot,
                %block_root,
                %index,
                "Successfully verified gossip data column sidecar"
            );

            self.propagate_validation_result(message_id, peer_id, MessageAcceptance::Accept);

